  "criteria": [
    {
      "id": "C1",
      "level": "Accomplished",
      "mark": 8,
      "evidence": [
        {
          "where": "1 Introduction",
          "quote": "The primary mission of ZYZZsat is to image the whole Great Barrier Reef in visible bands at 5 m resolution"
        },
        {
          "where": "1 Introduction",
          "quote": "One satellite is therefore used."
        },
        {
          "where": "1 Introduction",
          "quote": "The operator is the Australian Institute of Marine Science (AIMS)"
        }
      ],
      "reasoning": "The mission, Australian benefit, rationale, single-spacecraft choice, operator, customers, and public-service funding are clearly explained. References support the rationale, although some sources are secondary or incompletely detailed."
    },
    {
      "id": "C2",
      "level": "Adequate",
      "mark": 6,
      "evidence": [
        {
          "where": "2.2 Launch",
          "quote": "The baseline is an SSMS rideshare flight on Vega C from Kourou in early 2025"
        },
        {
          "where": "2.3 Orbit",
          "quote": "The orbit is circular, so it has no perigee"
        },
        {
          "where": "2.4 Ground Control & Communications",
          "quote": "There are six passes each day, three in the evening and three in the morning (UTC)"
        },
        {
          "where": "2.5 Mission Duration & EOL",
          "quote": "With a 4 m² sail the satellite re-enters about two years after the end of the mission."
        }
      ],
      "reasoning": "The report addresses launch, orbit and elements, access calculations, station, communications, duration, and disposal, with STK figures and detailed calculations. However, the orbital-decay calculation is wrong by about a factor of ten, undermining its EOL compliance claim; a link budget is also absent, and the orbit/revisit and payload assumptions are preliminary."
    },
    {
      "id": "C3",
      "level": "Accomplished",
      "mark": 8,
      "evidence": [
        {
          "where": "3 Conclusion",
          "quote": "The design has four limitations."
        },
        {
          "where": "3 Conclusion",
          "quote": "With these points addressed in the next design phase, the mission can provide the direct, regular bleaching maps"
        }
      ],
      "reasoning": "The conclusion synthesizes key design results and identifies meaningful limitations and follow-up work. It is specific to the evidence, though its positive EOL conclusion relies on the erroneous decay calculation."
    },
    {
      "id": "C4",
      "level": "Accomplished",
      "mark": 8,
      "evidence": [
        {
          "where": "Executive Summary",
          "quote": "This report presents the design of ZYZZsat (Z-axis/Y-axis Zeroed Zoning Satellite)"
        },
        {
          "where": "Contents",
          "quote": "Executive Summary\n1 Introduction\n2 Mission Design\n2.1 Spacecraft overview"
        },
        {
          "where": "Bibliography",
          "quote": "[11] D. A. Vallado, *Fundamentals of Astrodynamics and Applications*"
        },
        {
          "where": "Image 1",
          "quote": ""
        }
      ],
      "reasoning": "The report has a logical structure, concise executive summary, labelled figures and tables, readable technical prose, and a substantial bibliography with in-text citations. Presentation is generally professional. Some sources are weakly specified and some figures are not accompanied by underlying software outputs in the report, but the appendix identifies submitted STK files."
    }
  ],
